using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.VTS.Visitas;namespace GraphApi.Services.VTS.Visitas{    public class VisitasService : IVisitasService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public VisitasService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadVisitas>> GetVisitas(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM vts.Visitas (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadVisitas>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetVisitasDynamic(            int? visitaID,            string? visitanteNombre,            int? usuarioVisitadoID,            int? casaID,            int? tipoIdentificacionID,            string? numeroIdentificacion,            string? rutaDocumento,            DateTime? fechaEntrada,            DateTime? fechaSalida,            bool? autorizado,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "VisitaID, VisitanteNombre, UsuarioVisitadoID, CasaID, TipoIdentificacionID, NumeroIdentificacion, RutaDocumento, FechaEntrada, FechaSalida, Autorizado, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM vts.Visitas (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (visitaID.HasValue)            {                vSql.Append(" AND VisitaID = @VisitaID");                vParameters.Add("VisitaID",visitaID);            }            if (!string.IsNullOrWhiteSpace(visitanteNombre))            {                vSql.Append(" AND VisitanteNombre LIKE @VisitanteNombre");                vParameters.Add("VisitanteNombre",$"%{visitanteNombre}%");            }            if (!string.IsNullOrWhiteSpace(numeroIdentificacion))            {                vSql.Append(" AND NumeroIdentificacion LIKE @NumeroIdentificacion");                vParameters.Add("NumeroIdentificacion",$"%{numeroIdentificacion}%");            }            if (!string.IsNullOrWhiteSpace(rutaDocumento))            {                vSql.Append(" AND RutaDocumento LIKE @RutaDocumento");                vParameters.Add("RutaDocumento",$"%{rutaDocumento}%");            }            if (autorizado.HasValue)            {                vSql.Append(" AND Autorizado = @Autorizado");                vParameters.Add("Autorizado", autorizado.Value);            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadVisitas> CreateVisitas(clCreateVisitas objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO vts.Visitas                (VisitanteNombre, UsuarioVisitadoID, CasaID, TipoIdentificacionID, NumeroIdentificacion, RutaDocumento, FechaEntrada, FechaSalida, Autorizado, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@VisitanteNombre, @UsuarioVisitadoID, @CasaID, @TipoIdentificacionID, @NumeroIdentificacion, @RutaDocumento, @FechaEntrada, @FechaSalida, @Autorizado, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.VisitanteNombre,                objInput.UsuarioVisitadoID,                objInput.CasaID,                objInput.TipoIdentificacionID,                objInput.NumeroIdentificacion,                objInput.RutaDocumento,                objInput.FechaEntrada,                objInput.FechaSalida,                objInput.Autorizado,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT VisitaID, VisitanteNombre, UsuarioVisitadoID, CasaID, TipoIdentificacionID, NumeroIdentificacion, RutaDocumento, FechaEntrada, FechaSalida, Autorizado, bEliminado                FROM vts.Visitas (NOLOCK)                WHERE VisitaID = @VisitaID;";            var vReadParams = new { VisitaID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadVisitas>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el Visita con ID {vNewId}.");            return vCreated;        }        public async Task<clReadVisitas?> UpdateVisitas(clUpdateVisitas objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("VisitaID", objInput.VisitaID);            if (objInput.VisitanteNombre is not null)            {                vSets.Add("VisitanteNombre = @VisitanteNombre");                vParameters.Add("VisitanteNombre", objInput.VisitanteNombre);            }            if (objInput.UsuarioVisitadoID != null)            {                vSets.Add("UsuarioVisitadoID = @UsuarioVisitadoID");                vParameters.Add("UsuarioVisitadoID", objInput.UsuarioVisitadoID);            }            if (objInput.CasaID != null)            {                vSets.Add("CasaID = @CasaID");                vParameters.Add("CasaID", objInput.CasaID);            }            if (objInput.TipoIdentificacionID != null)            {                vSets.Add("TipoIdentificacionID = @TipoIdentificacionID");                vParameters.Add("TipoIdentificacionID", objInput.TipoIdentificacionID);            }            if (objInput.NumeroIdentificacion is not null)            {                vSets.Add("NumeroIdentificacion = @NumeroIdentificacion");                vParameters.Add("NumeroIdentificacion", objInput.NumeroIdentificacion);            }            if (objInput.RutaDocumento is not null)            {                vSets.Add("RutaDocumento = @RutaDocumento");                vParameters.Add("RutaDocumento", objInput.RutaDocumento);            }            if (objInput.FechaEntrada != null)            {                vSets.Add("FechaEntrada = @FechaEntrada");                vParameters.Add("FechaEntrada", objInput.FechaEntrada);            }            if (objInput.FechaSalida != null)            {                vSets.Add("FechaSalida = @FechaSalida");                vParameters.Add("FechaSalida", objInput.FechaSalida);            }            if (objInput.Autorizado != null)            {                vSets.Add("Autorizado = @Autorizado");                vParameters.Add("Autorizado", objInput.Autorizado);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE vts.Visitas                SET {vSetClause}                WHERE VisitaID = @VisitaID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT VisitaID, VisitanteNombre, UsuarioVisitadoID, CasaID, TipoIdentificacionID, NumeroIdentificacion, RutaDocumento, FechaEntrada, FechaSalida, Autorizado, bEliminado                FROM vts.Visitas (NOLOCK)                WHERE VisitaID = @VisitaID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadVisitas>(sSelect, new {  objInput.VisitaID });        }        public async Task<bool> DeleteVisitas(int nVisitasID)        {            const string sSql = @"                DELETE FROM vts.Visitas                WHERE VisitaID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nVisitasID });            return vAffected > 0;        }    }}